from h import P
R=[
(8543483,"अरबी कॉफ़ी","सऊदी (अरबी) कॉफ़ी हल्के भुने बीजों को बर्तन में उबालकर बनाई जाती है, फिर इसे इलायची, केसर और लौंग के ऊपर दल्ला में डाला जाता है और छोटे फिंजान में खजूर के साथ परोसा जाता है; यूनेस्को ने इसे अमूर्त सांस्कृतिक विरासत की सूची में रखा है। हमारे नुस्खे में चीनी नहीं है और न ही कॉफ़ी क्रीमर या मिल्क पाउडर है, और खजूर की मात्रा सीमित है।","6","3 फिंजान (150 मिलीलीटर) और 2 छोटे खजूर",
["3 बड़े चम्मच हल्की भुनी अरबी कॉफ़ी, मध्यम पिसी हुई (30 ग्राम)","1 लीटर पानी","1 बड़ा चम्मच ताज़ा पिसी इलायची (8 ग्राम)","एक चुटकी केसर (लगभग 10 धागे)","3 साबुत लौंग","परोसने के लिए 12 छोटे खजूर (लगभग 96 ग्राम)"],
["पानी को कॉफ़ी के बर्तन (मुल्गमा) में उबालें, फिर आँच धीमी कर दें।","कॉफ़ी डालें, एक बार चलाएँ और उफनने दिए बिना 12–15 मिनट धीमी आँच पर पकने दें।","आँच बंद करें, ढक दें और 3–5 मिनट रहने दें ताकि कॉफ़ी की तलछट नीचे बैठ जाए।","इलायची, केसर और लौंग को दल्ला या फ्लास्क में डालें, फिर तलछट को छोड़ते हुए कॉफ़ी को उन पर धीरे-धीरे उड़ेलें।","2 मिनट तक सुगंध उतरने दें, फिर फिंजान में खजूर के साथ परोसें।"],
["क्या बदला गया: इसमें चीनी, कॉफ़ी क्रीमर या मिल्क पाउडर नहीं है (जो कुछ आधुनिक नुस्खों में डाला जाता है), और साथ में मिठाई की जगह 3 फिंजान के साथ 2 छोटे खजूर की मात्रा रखी गई है।","किडनी के लिए सुझाव: इस मात्रा में कॉफ़ी में पोटैशियम कम होता है, लेकिन खजूर में पोटैशियम अधिक होता है; अधिकतम 2 खजूर ही लें, और यदि आपके लिए तरल की दैनिक सीमा तय है तो कॉफ़ी को उसमें गिनें।","मधुमेह और रक्तचाप के लिए सुझाव: एक सर्विंग में लगभग 13 ग्राम कार्बोहाइड्रेट होता है, जो सारा खजूर से आता है; 2 खजूर से अधिक न लें, और दिन में 3–4 फिंजान तक ही पिएँ क्योंकि कैफ़ीन कुछ समय के लिए रक्तचाप बढ़ा सकती है।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग, किडनी रोग (डायलिसिस पर नहीं), डायलिसिस पर रहने वाले लोग, शाकाहारी, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग (मौसूअत अल तबख), सऊदीपीडिया, सैयदाती किचन"],[]),
(8546041,"क़ुर्स अल-मुल्ला ब्रेड","क़ुर्स अल-मुल्ला, जिसे क़ुर्स अल-जमर भी कहा जाता है, साबुत गेहूँ के आटे, पानी और नमक से बनी पुरानी बदू सऊदी रोटी है, जिसे गरम राख और अंगारों में दबाकर पकाया जाता है, फिर चूरकर घी के साथ परोसा जाता है। यह घरेलू नुस्खा रोटी को ओवन या ढक्कन वाले कास्ट-आयरन बर्तन में सेंकता है, घी नाप कर डालता है और चीनी की जगह थोड़ा शहद इस्तेमाल करता है।","6","घी के साथ चूरी हुई रोटी का 1 हिस्सा (लगभग 85 ग्राम)",
["300 ग्राम साबुत गेहूँ का आटा","लगभग 200 मिलीलीटर गुनगुना पानी","½ छोटा चम्मच नमक (3 ग्राम)","5 छोटे चम्मच घी (24 ग्राम)","परोसने के लिए 1½ बड़े चम्मच शहद (30 ग्राम), वैकल्पिक"],
["आटे को नमक के साथ मिलाएँ, पानी थोड़ा-थोड़ा करके डालें और 8–10 मिनट गूँधकर सख़्त आटा बना लें जो हाथों से न चिपके; ढक दें और 15 मिनट रखा रहने दें।","ओवन को 230 °C पर गरम करें और कम से कम 20 मिनट तक उसमें कास्ट-आयरन की ट्रे या बेकिंग स्टोन रखें।","आटे को हाथ से दबाकर लगभग 22–25 सेमी चौड़ा और 2 सेमी मोटा गोला बनाएँ और काँटे से गोद दें।","गोले को गरम ट्रे पर रखें और 35–40 मिनट सेंकें, बीच में पलट दें, जब तक दोनों तरफ़ से भूरा न हो जाए और थपथपाने पर खोखली आवाज़ न आए। (बाहर इसे परंपरागत रूप से लगभग एक घंटे राख और अंगारों में दबाया जाता है, फिर ब्रश से साफ़ किया जाता है।)","जला हुआ ऊपरी हिस्सा झाड़ दें, फिर गरम रोटी को हाथ से चूर लें या परोसने के बर्तन में छोटे टुकड़ों में काट लें।","घी पिघलाकर चूरे पर डालें और साथ में मिलाएँ, चाहें तो शहद छिड़कें और गरम परोसें।"],
["क्या बदला गया: साबुत गेहूँ का आटा, सीमित नमक (प्रति हिस्सा ½ ग्राम), सामान्य से बहुत कम घी (प्रति हिस्सा 1 छोटे चम्मच से कम), और चीनी की जगह थोड़ा वैकल्पिक शहद।","किडनी के लिए सुझाव: साबुत गेहूँ के आटे में मैदे से अधिक फॉस्फोरस और पोटैशियम होता है; आप आधा आटा मैदे से बदल सकते हैं और एक ही हिस्सा खाएँ।","मधुमेह के लिए सुझाव: एक हिस्से में लगभग 40 ग्राम कार्बोहाइड्रेट होता है; शहद छोड़ दें और इसे कम वसा वाली लबन या उबले अंडे और सलाद के साथ परोसें।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग, किडनी रोग (डायलिसिस पर नहीं), डायलिसिस पर रहने वाले लोग, शाकाहारी।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, अल वतन (सऊदी अख़बार), अल ख़लीज पत्रिका"],[]),
(8546606,"फ़ॉइल में चिकन","फ़ॉइल में चिकन (क़स्दीर) घर और कैंपिंग का लोकप्रिय व्यंजन है: चिकन के टुकड़ों को प्याज़, टमाटर, शिमला मिर्च, मिली-जुली सब्ज़ियों और काबुली चने के साथ मसाले लगाकर फ़ॉइल में बंद किया जाता है और चूल्हे या अंगारों पर अपने ही रस में नरम होने तक पकाया जाता है। यहाँ चिकन बिना त्वचा का है, स्टॉक क्यूब की जगह घर का बना बिना नमक वाला स्टॉक इस्तेमाल हुआ है, और केवल एक चम्मच ऑलिव ऑयल तथा थोड़ा नमक डाला गया है।","4","चिकन और सब्ज़ियों की 1 प्लेट (लगभग 400 ग्राम)",
["300 ग्राम बिना त्वचा की चिकन ब्रेस्ट, बड़े टुकड़ों में कटी हुई","300 ग्राम बिना त्वचा और बिना हड्डी की चिकन जाँघ, कटी हुई","1 मध्यम प्याज़, कटा हुआ (150 ग्राम)","2 टमाटर, कटे हुए (200 ग्राम)","1 हरी शिमला मिर्च, कटी हुई (150 ग्राम)","250 ग्राम जमी हुई मिली-जुली सब्ज़ियाँ (मटर और गाजर)","120 ग्राम डिब्बाबंद काबुली चने, छने हुए और अच्छी तरह धोए हुए","2 लहसुन की कलियाँ, बारीक कटी हुई (10 ग्राम)","1 नींबू का रस (30 मिलीलीटर)","1 बड़ा चम्मच ऑलिव ऑयल (15 मिलीलीटर)","1 छोटा चम्मच करी पाउडर, 1 छोटा चम्मच मिश्रित मसाला (बज़ार), ½ छोटा चम्मच हल्दी, ½ छोटा चम्मच काली मिर्च","⅘ छोटा चम्मच नमक (5 ग्राम)","120 मिलीलीटर घर का बना बिना नमक वाला चिकन स्टॉक या गरम पानी"],
["एक बड़े कटोरे में चिकन को प्याज़, टमाटर, शिमला मिर्च, जमी सब्ज़ियों, काबुली चने और लहसुन के साथ मिलाएँ।","नींबू का रस, तेल, मसाले और नमक को स्टॉक में फेंटें, इसे चिकन और सब्ज़ियों पर डालें और अच्छी तरह मिलाएँ ताकि सब पर लग जाए।","एक चौड़े बर्तन या ट्रे में फ़ॉइल की दो परतें आर-पार बिछाएँ, मिश्रण को बीच में रखें और फ़ॉइल को चारों तरफ़ से कसकर बंद करें ताकि भाप बाहर न निकले।","पोटली को बर्तन में धीमी आँच पर 50–60 मिनट पकाएँ (या ओवन में 200 °C पर 45–50 मिनट, या अंगारों पर) जब तक चिकन पूरी तरह पक न जाए।","भाप से बचते हुए फ़ॉइल को सावधानी से खोलें, जाँच लें कि चिकन अंदर तक पक गया है, और गरम-गरम सलाद या थोड़े बासमती चावल या रोटी के साथ परोसें।"],
["क्या बदला गया: मैगी क्यूब नहीं है (उसकी जगह घर का बना बिना नमक वाला स्टॉक और मसाले), बिना त्वचा का चिकन, पूरे व्यंजन में एक चम्मच तेल, और सोडियम घटाने के लिए धोए हुए डिब्बाबंद काबुली चने।","किडनी के लिए सुझाव: काबुली चने, टमाटर और मटर में पोटैशियम और फॉस्फोरस होता है; आप चने छोड़ सकते हैं या आधे कर सकते हैं, टमाटर की जगह तोरी या पत्तागोभी ले सकते हैं, और चिकन 90–120 ग्राम तक ही रखें।","मधुमेह के लिए सुझाव: एक हिस्से में केवल लगभग 22 ग्राम कार्बोहाइड्रेट होता है; यदि चावल के साथ परोस रहे हैं तो सलाद के साथ लगभग 75 ग्राम पके बासमती चावल तक ही रखें।","इनके लिए उपयुक्त: मधुमेह वाले लोग, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, कुकपैड सऊदी अरब, सैयदाती किचन"],[]),
(8547419,"क़ुर्सान","क़ुर्सान नज्द का व्यंजन है जिसमें पतली, सुखाई हुई साबुत गेहूँ की रोटी (क़ुर्सान ब्रेड) को तोड़कर मांस और सब्ज़ियों के शोरबे और सूखे नींबू वाले प्याज़ के साथ परतों में लगाया जाता है, जब तक वह सब सोख न ले। इस नुस्खे में रोटी घर पर साबुत गेहूँ के आटे से बिना वसा के बनाई जाती है, साथ में कम वसा वाला मांस, भरपूर सब्ज़ियाँ और थोड़ा ऑलिव ऑयल है, ऊपर से चीनी, खुबानी का पेस्ट या मक्खन नहीं डाला जाता, और नमक कम है।","4","1 प्लेट (लगभग 500 ग्राम)",
["क़ुर्सान ब्रेड के लिए::200 ग्राम साबुत गेहूँ का आटा, एक चुटकी नमक (1 ग्राम) और लगभग 130 मिलीलीटर पानी (या 200 ग्राम तैयार सूखा साबुत गेहूँ का क़ुर्सान)","शोरबे के लिए::560 ग्राम कम वसा वाली मेमने की जाँघ, छोटे टुकड़ों में कटी हुई","शोरबे के लिए::1½ बड़े चम्मच ऑलिव ऑयल (20 ग्राम)","शोरबे के लिए::1 बड़ा प्याज़, कटा हुआ (150 ग्राम)","शोरबे के लिए::2 टमाटर, ब्लेंड किए हुए (200 ग्राम)","शोरबे के लिए::1½ बड़े चम्मच बिना नमक वाला टमाटर पेस्ट (20 ग्राम)","शोरबे के लिए::1 छोटा चम्मच हल्दी, 1 छोटा चम्मच जीरा, 1 छोटा चम्मच पिसा धनिया, ½ छोटा चम्मच काली मिर्च, 2 छेदे हुए सूखे नींबू, 3 इलायची","शोरबे के लिए::1 गाजर (100 ग्राम), 1 तोरी (150 ग्राम), 1 छोटा बैंगन (150 ग्राम), 200 ग्राम कद्दू और 100 ग्राम हरी फलियाँ, टुकड़ों में कटी हुई","शोरबे के लिए::2 साबुत लाल मिर्च (20 ग्राम)","शोरबे के लिए::½ छोटा चम्मच नमक (3 ग्राम)","शोरबे के लिए::लगभग 1.2 लीटर उबलता पानी","परतों के लिए::1 मध्यम प्याज़, बारीक कटा हुआ (100 ग्राम), साथ में 1 छोटा चम्मच पिसा सूखा नींबू, ½ छोटा चम्मच दालचीनी और एक-एक चुटकी इलायची और हल्दी","परतों के लिए::2 हरे प्याज़, कटे हुए (20 ग्राम)"],
["क़ुर्सान ब्रेड के लिए: आटे, नमक और पानी को चिकना होने तक गूँधें, 30 मिनट रखा रहने दें, फिर 4 गोले बनाएँ और हर एक को बहुत पतला बेलें।","हर रोटी को गरम सूखे साज या तवे पर प्रति तरफ़ 1–2 मिनट सेंकें जब तक वह सूख न जाए और उस पर धब्बे न पड़ जाएँ, फिर ठंडा होने दें और अपनी हथेली के लगभग आधे आकार के टुकड़ों में तोड़ लें।","शोरबे के लिए: बर्तन में तेल गरम करें और प्याज़ को नरम करें, फिर मांस डालें और रंग बदलने तक चलाएँ; मसाले, टमाटर और टमाटर पेस्ट डालें और 5 मिनट गाढ़ा होने दें।","उबलता पानी डालें, सूखे नींबू और मिर्च डालें और मध्यम आँच पर 45 मिनट पकाएँ जब तक मांस लगभग नरम न हो जाए (या प्रेशर कुकर में 25 मिनट)।","गाजर डालें, फिर 5 मिनट बाद बाकी सब्ज़ियाँ और नमक डालें और 15–20 मिनट पकाएँ जब तक नरम न हो जाएँ; फिर मांस निकालकर अलग रख लें।","ओवन को 180°C पर गरम करें। ओवन में रखने लायक बर्तन या गहरे डिश में थोड़ा शोरबा डालें, फिर क़ुर्सान की एक परत, फिर सब्ज़ियों वाला शोरबा, फिर थोड़ा प्याज़ और सूखा नींबू रखें; सब ख़त्म होने तक दोहराएँ।","कई जगह परतों में चम्मच नीचे तक दबाएँ ताकि शोरबा सारी रोटी तक पहुँचे, मांस को बीच में सजाएँ, फ़ॉइल से ढकें और 25–30 मिनट सेंकें जब तक शोरबा सोख न लिया जाए।","हरे प्याज़ छिड़कें और गरम परोसें।"],
["क्या बदला गया: घर की बनी बिना वसा की साबुत गेहूँ की क़ुर्सान, ऊपर से चीनी, खुबानी का पेस्ट या भूरा किया मक्खन नहीं, कम वसा वाला मांस, थोड़ा तेल, अधिक सब्ज़ियाँ और सामान्य से लगभग आधा नमक; खजूर वाले मसना मसाले की जगह सूखा नींबू, दालचीनी और इलायची।","किडनी के लिए सुझाव: साबुत गेहूँ का आटा, कद्दू, टमाटर, टमाटर पेस्ट, गाजर और मांस में पोटैशियम और फॉस्फोरस अधिक होता है; एक ही प्लेट लें, और आप कद्दू और टमाटर आधे करके तोरी और हरी फलियाँ बढ़ा सकते हैं। अपनी मात्रा के बारे में अपने आहार विशेषज्ञ से पूछें।","मधुमेह के लिए सुझाव: एक प्लेट में लगभग 57 ग्राम कार्बोहाइड्रेट और 11 ग्राम फाइबर होता है; क़ुर्सान इस भोजन का स्टार्च है, इसलिए रोटी या चावल न जोड़ें, और हरा सलाद साथ रखें।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग।","संदर्भ: एनसाइक्लोपीडिया कुकिंग (encyclopediacooking.com), अरबी विकिपीडिया (क़ुर्सान), सऊदीपीडिया (क़ुर्सान)"],[]),
(8549296,"हिजाज़ी सुलत लहम","सुलत मदीना और मक्का का लोकप्रिय हिजाज़ी व्यंजन है: मेमने के टुकड़ों को प्याज़, लहसुन, जीरे और काली मिर्च के साथ धीमी आँच पर तब तक पकाया जाता है जब तक सॉस गाढ़ा न हो जाए, और पतली रोटी के साथ परोसा जाता है। इस नुस्खे में पिघली चर्बी और घी की जगह कम वसा वाली मेमने की जाँघ, दो छोटे चम्मच ऑलिव ऑयल, थोड़ा नमक, साबुत गेहूँ की रोटी और ताज़ा सलाद है।","4","मांस की सॉस, रोटी और सलाद की 1 प्लेट (लगभग 380 ग्राम)",
["सुलत के लिए::520 ग्राम कम वसा वाली बिना हड्डी की मेमने की जाँघ, छोटे टुकड़ों में कटी हुई, दिखने वाली चर्बी हटाई हुई","सुलत के लिए::2 छोटे चम्मच ऑलिव ऑयल (10 मिलीलीटर)","सुलत के लिए::1 मध्यम प्याज़, कद्दूकस किया हुआ या बारीक कटा हुआ (150 ग्राम)","सुलत के लिए::200 ग्राम छोटे प्याज़ (छिले हुए साबुत छोटे प्याज़)","सुलत के लिए::6 लहसुन की कलियाँ, बारीक कटी हुई (30 ग्राम)","सुलत के लिए::1–2 तीखी हरी मिर्च, कटी हुई (15 ग्राम), स्वादानुसार","सुलत के लिए::1 छोटा चम्मच पिसा जीरा, ½ छोटा चम्मच काली मिर्च, ½ छोटा चम्मच हल्दी (हुर्द), 1 छोटा चम्मच मिश्रित मसाला (बज़ार)","सुलत के लिए::½ छोटा चम्मच नमक (3 ग्राम)","सुलत के लिए::लगभग 700 मिलीलीटर उबलता पानी","परोसने के लिए::4 छोटी पतली साबुत गेहूँ की रोटियाँ (140 ग्राम)","परोसने के लिए::2 खीरे (200 ग्राम) और 1 टमाटर (150 ग्राम), टुकड़ों में कटे हुए","परोसने के लिए::सलाद के लिए ½ नींबू का रस (20 मिलीलीटर) और एक छोटी चुटकी नमक (1 ग्राम)"],
["नॉन-स्टिक बर्तन में तेज़-मध्यम आँच पर तेल गरम करें, कद्दूकस किया प्याज़ डालें और 4–5 मिनट चलाएँ जब तक नरम और हल्का सुनहरा न हो जाए।","लहसुन और हरी मिर्च डालकर 1 मिनट चलाएँ, फिर जीरा, काली मिर्च, हल्दी और मसाले डालें और 30 सेकंड तक चलाएँ जब तक सुगंध न आने लगे।","मेमना डालें और तेज़ आँच पर चलाएँ जब तक उसका रंग न बदल जाए और रस लगभग सूख न जाए (लगभग 10 मिनट)।","उबलता पानी और छोटे प्याज़ डालें, ढक दें, आँच धीमी करें और 1–1¼ घंटे धीमे-धीमे पकाएँ, बीच-बीच में चलाते रहें, जब तक मांस नरम न हो जाए और सॉस कम होकर गाढ़ा न हो जाए।","अंत में नमक डालें और चखें; यदि सॉस अब भी पतला है तो ढक्कन हटाकर 10 मिनट और पकाएँ।","खीरे और टमाटर को नींबू के रस और चुटकी भर नमक के साथ मिलाएँ, और सुलत को पतली रोटी और सलाद के साथ गरम परोसें।"],
["क्या बदला गया: चर्बी के टुकड़े पिघलाने की जगह कम वसा वाली मेमने की जाँघ, पूरे बर्तन के लिए 2 छोटे चम्मच ऑलिव ऑयल, अंत में थोड़ा नमक, और साबुत गेहूँ की रोटी के साथ ताज़ा सलाद।","किडनी के लिए सुझाव: मांस और टमाटर में फॉस्फोरस और पोटैशियम होता है; पका हुआ मांस 90–100 ग्राम तक ही रखें, रोटी पर कम सॉस डालें, और टमाटर की जगह अधिक खीरा ले सकते हैं।","मधुमेह के लिए सुझाव: एक हिस्से में लगभग 34 ग्राम कार्बोहाइड्रेट होता है, ज़्यादातर रोटी से; एक ही छोटी रोटी लें और सलाद से पेट भरें।","इनके लिए उपयुक्त: मधुमेह वाले लोग।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, सैयदाती किचन, कुकपैड सऊदी अरब"],[]),
(8556931,"दग़ूस टमाटर सॉस","दग़ूस टमाटर, मिर्च, लहसुन और नींबू से बनी तीखी सऊदी सॉस है जो कब्सा और मंदी के साथ परोसी जाती है। इस नुस्खे में केचप या स्टॉक क्यूब नहीं हैं, बिना नमक वाला टमाटर पेस्ट इस्तेमाल हुआ है और नमक बहुत कम है।","4","लगभग 4 बड़े चम्मच (120 ग्राम)",
["4 मध्यम टमाटर, चौथाई में कटे हुए (400 ग्राम)","2 हरी मिर्च (20 ग्राम) और 1 लाल मिर्च (10 ग्राम), चाहें तो बीज निकाले हुए","3 लहसुन की कलियाँ (10 ग्राम)","1 बड़ा चम्मच बिना नमक वाला टमाटर पेस्ट (15 ग्राम)","1 बड़ा चम्मच ऑलिव ऑयल (13.5 ग्राम)","2 बड़े चम्मच नींबू का रस (30 मिलीलीटर)","2 छोटे चम्मच सेब का सिरका (10 मिलीलीटर)","2 बड़े चम्मच कटा अजमोद (10 ग्राम)","½ छोटा चम्मच जीरा, ¼ छोटा चम्मच कब्सा मसाला मिश्रण","⅓ छोटा चम्मच नमक (2 ग्राम)","60 मिलीलीटर पानी"],
["टमाटर, मिर्च और लहसुन को चिकना होने तक ब्लेंड करें।","इसे मध्यम आँच पर एक छोटी कड़ाही में डालें, टमाटर पेस्ट, जीरा, कब्सा मसाले और पानी डालें, उबाल आने दें, फिर 10 मिनट धीमी आँच पर पकाएँ जब तक थोड़ा गाढ़ा न हो जाए।","ऑलिव ऑयल, नींबू का रस, सिरका और नमक डालें और धीमी आँच पर 3 मिनट चलाएँ।","आँच से उतारें, अजमोद मिलाएँ और कब्सा के साथ गरम या ठंडा परोसें। इसे बंद जार में फ्रिज में 4 दिन तक रखा जा सकता है।"],
["क्या बदला गया: केचप (जिसमें चीनी और नमक अधिक होता है) और स्टॉक क्यूब नहीं हैं, बिना नमक वाला टमाटर पेस्ट है, बहुत सारे तेल की जगह एक चम्मच तेल है, और नमक की जगह नींबू और सिरके से खटास दी गई है।","किडनी के लिए सुझाव: टमाटर में पोटैशियम अधिक होता है; भोजन के साथ दग़ूस के 2 बड़े चम्मच ही लें, और आधे टमाटर की जगह भुनी लाल शिमला मिर्च डाल सकते हैं।","मधुमेह के लिए सुझाव: दग़ूस में कार्बोहाइड्रेट कम होता है (प्रति हिस्सा लगभग 7 ग्राम) और इसका स्वाद आपको कम चावल खाने में मदद करता है।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग, किडनी रोग (डायलिसिस पर नहीं), डायलिसिस पर रहने वाले लोग, शाकाहारी, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग (encyclopediacooking.com), सैयदाती किचन (सऊदी दग़ूस), अतयब तबख़ा (कब्सा के लिए तीखा दग़ूस)"],[]),
(8557472,"हिजाज़ी मांस मुअर्रक़","मुअर्रक़ मदीना और हिजाज़ का व्यंजन है जिसमें मांस को इलायची और मस्तकी के साथ भूरा किया जाता है, फिर टमाटर और प्याज़ की सॉस में नरम होने तक धीमी आँच पर पकाया जाता है और सादे चावल के साथ परोसा जाता है। हमने कम वसा वाला जाँघ का मांस, 1 छोटा चम्मच घी के साथ ऑलिव ऑयल, और कम बिना नमक वाला टमाटर पेस्ट इस्तेमाल किया है।","4","1 प्लेट (चावल सहित लगभग 400 ग्राम)",
["मांस के लिए::500 ग्राम कम वसा वाली मेमने की जाँघ, मध्यम टुकड़ों में कटी हुई","मांस के लिए::1 बड़ा चम्मच ऑलिव ऑयल (13.5 ग्राम) और 1 छोटा चम्मच घी (4.5 ग्राम)","मांस के लिए::3 इलायची और 5 छोटे मस्तकी के दाने","मांस के लिए::1 मध्यम प्याज़, कद्दूकस किया हुआ (150 ग्राम)","मांस के लिए::4 लहसुन की कलियाँ, कुटी हुई (15 ग्राम)","मांस के लिए::1 बड़ा चम्मच बिना नमक वाला टमाटर पेस्ट (15 ग्राम)","मांस के लिए::3 मध्यम टमाटर, ब्लेंड किए हुए (300 ग्राम)","मांस के लिए::½ छोटा चम्मच मिश्रित मसाला, ½ छोटा चम्मच काली मिर्च, ½ छोटा चम्मच लाल मिर्च पाउडर","मांस के लिए::½ छोटा चम्मच नमक (2.5 ग्राम)","मांस के लिए::500 मिलीलीटर गरम पानी","चावल के लिए::200 ग्राम बासमती चावल, धोए हुए और 20 मिनट भिगोए हुए","चावल के लिए::¼ छोटा चम्मच नमक (1.5 ग्राम) और 400 मिलीलीटर पानी"],
["बर्तन में मध्यम आँच पर इलायची और मस्तकी के साथ तेल और घी गरम करें जब तक सुगंध न आने लगे।","मांस डालें और चलाएँ जब तक वह भूरा न हो जाए, रस छोड़े और वह सूख जाए।","प्याज़, लहसुन और टमाटर पेस्ट डालकर 3 मिनट चलाएँ, फिर ब्लेंड किए टमाटर डालें और तब तक पकाएँ जब तक उनका ज़्यादातर पानी उड़ न जाए।","मसाले, नमक और गरम पानी डालें, ढक दें और धीमी आँच पर 1 घंटा पकाएँ जब तक मांस नरम और सॉस गाढ़ी न हो जाए।","इस बीच चावल का पानी और नमक उबालें, छाने हुए चावल डालें, ढक दें और धीमी आँच पर 15 मिनट पकाएँ।","मुअर्रक़ को चावल के ऊपर या बगल में हरे सलाद के साथ परोसें।"],
["क्या बदला गया: हड्डी वाले चर्बीदार मांस की जगह कम वसा वाला जाँघ का मांस, 2 बड़े चम्मच की जगह 1 छोटा चम्मच घी, आधा टमाटर पेस्ट और ऊपर से नमक नहीं, और चावल की तय मात्रा।","किडनी के लिए सुझाव: टमाटर पेस्ट, टमाटर और मांस में पोटैशियम और फॉस्फोरस अधिक होता है; आप पेस्ट छोड़ सकते हैं, और मांस का एक ही हिस्सा (पका हुआ लगभग 90 ग्राम) थोड़ी सॉस के साथ लें।","मधुमेह के लिए सुझाव: प्लेट में चावल से लगभग 48 ग्राम कार्बोहाइड्रेट होता है; सलाद से शुरुआत करें, और एक तिहाई चावल की जगह ब्राउन राइस ले सकते हैं या साबुत गेहूँ की रोटी के साथ परोस सकते हैं।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग (encyclopediacooking.com), यम्मी (लयालीना), शो तबख़ा"],[]),
(8563508,"दक्षिणी अरीका","अरीका दक्षिणी सऊदी अरब (असीर और अल-बाहा) की पारंपरिक मिठाई है: साबुत गेहूँ के आटे को सेंका जाता है, गरम-गरम मसला जाता है और घी, शहद और खजूर के साथ अरबी कॉफ़ी के साथ परोसा जाता है। इस नुस्खे में भुना हुआ साबुत गेहूँ का आटा, थोड़ा घी, सामान्य से आधा शहद और मिठास के लिए खजूर, और छोटा हिस्सा है।","6","1 छोटा कटोरा (120 ग्राम)",
["आटे के लिए::240 ग्राम साबुत गेहूँ (बुर) का आटा","आटे के लिए::500 मिलीलीटर गुनगुना पानी","आटे के लिए::1 चुटकी नमक (1 ग्राम)","आटे के लिए::बर्तन चिकना करने के लिए 1 छोटा चम्मच घी (5 ग्राम)","परोसने के लिए::2 छोटे चम्मच घी (10 ग्राम)","परोसने के लिए::2 बड़े चम्मच शहद (42 ग्राम)","परोसने के लिए::6 खजूर, गुठली निकाले हुए (60 ग्राम)"],
["साबुत गेहूँ के आटे को सूखे बर्तन में धीमी आँच पर 3–4 मिनट चलाते हुए भूनें जब तक उसमें भुनी हुई सुगंध न आने लगे, फिर थोड़ा ठंडा होने दें।","नमक डालें, फिर धीरे-धीरे गुनगुना पानी डालकर नरम आटा बना लें जो केक के घोल से थोड़ा गाढ़ा हो; इसे 15 मिनट रखा रहने दें।","नॉन-स्टिक कड़ाही या ट्रे पर पहला छोटा चम्मच घी लगाएँ, उसमें आटा फैलाएँ और 200 °C पर गरम किए ओवन में लगभग 30 मिनट सेंकें, या धीमी आँच पर एक बार पलटते हुए दोनों तरफ़ से पकाएँ।","गरम रहते हुए रोटी को साफ़ थैली या कटोरे में रखें और हाथों से (कपड़े से बचाकर) तब तक मसलें जब तक वह चिकनी और एकसार न हो जाए। यदि सूख जाए तो एक चम्मच गरम पानी डालें।","इसे परोसने के कटोरे में आकार दें, बीच में गड्ढा बनाएँ, उसमें पिघला घी डालें, किनारे पर शहद की धार डालें और खजूर से सजाएँ।","6 छोटे हिस्सों में बाँटें और अरबी कॉफ़ी के साथ गरम परोसें।"],
["क्या बदला गया: मैदे की जगह साबुत गेहूँ का आटा, ढेर सारे घी की जगह प्रति हिस्सा लगभग 2.5 ग्राम घी, सामान्य से आधा शहद और मिठास के लिए खजूर, और छोटे हिस्से।","किडनी के लिए सुझाव: साबुत गेहूँ के आटे और खजूर में मैदे से अधिक फॉस्फोरस और पोटैशियम होता है; एक ही हिस्सा लें, और आप आधा साबुत गेहूँ का आटा मैदे से बदल सकते हैं और प्रति हिस्सा एक खजूर रख सकते हैं।","मधुमेह के लिए सुझाव: एक हिस्से में लगभग 42 ग्राम कार्बोहाइड्रेट होता है; इसे अपने भोजन में गिनें, बिना चीनी की कॉफ़ी के साथ लें और ऊपर से और शहद न डालें।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग, किडनी रोग (डायलिसिस पर नहीं), डायलिसिस पर रहने वाले लोग, शाकाहारी।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, यम्मी लयालीना, बयूत"],[]),
(8567106,"हसावी बकरे का मंदी","हसावी मंदी अल-अहसा का मशहूर व्यंजन है, जो दावतों के लिए बनाया जाता है: बकरे का मांस ज़मीन के भीतर बने तंदूर में चावल के बर्तन के ऊपर पकता है और खजूर की डालियों के आधार से धुआँ दिया जाता है। यह घर के ओवन में बनने वाला नुस्खा है जिसमें कम वसा वाला बकरे का मांस, थोड़ा घी और कम नमक है।","4","1 प्लेट (लगभग 400 ग्राम)",
["मांस के लिए::600 ग्राम जाँघ या कंधे का बकरे का मांस, दिखने वाली चर्बी हटाई हुई, बड़े टुकड़ों में","मांस के लिए::1 छोटा चम्मच मिश्रित मसाला, ¼ छोटा चम्मच पिसा केसर 2 बड़े चम्मच पानी में भिगोया हुआ","चावल के लिए::200 ग्राम लंबे दाने वाला बासमती चावल, धोया हुआ और 30 मिनट भिगोया हुआ","चावल के लिए::1 बड़ा चम्मच ऑलिव ऑयल (13.5 ग्राम) और 2 छोटे चम्मच घी (9 ग्राम)","चावल के लिए::1 बड़ा प्याज़, कटा हुआ (150 ग्राम)","चावल के लिए::1 बड़ा टमाटर, कटा हुआ (150 ग्राम)","चावल के लिए::1 हरी शिमला मिर्च, कटी हुई (80 ग्राम)","चावल के लिए::1 छोटी हरी मिर्च (10 ग्राम)","चावल के लिए::साबुत मसाले: 5 इलायची, 1 दालचीनी की डंडी, 3 लौंग, 1 छेदा हुआ सूखा नींबू (लूमी)","चावल के लिए::¾ छोटा चम्मच नमक (4 ग्राम), मांस और चावल में बाँटकर","चावल के लिए::360 मिलीलीटर गरम पानी","धुआँ देने के लिए 1 कोयले का टुकड़ा या खजूर की डाली के आधार का एक छोटा सूखा टुकड़ा (वैकल्पिक)"],
["बकरे के मांस पर मसाले और ¼ छोटा चम्मच नमक मलें, केसर का पानी छिड़कें और 30 मिनट रखा रहने दें।","ओवन को 170°C पर गरम करें। ओवन में रखने लायक बर्तन में प्याज़ को तेल और घी में नरम करें, फिर टमाटर, शिमला मिर्च, मिर्च और साबुत मसाले डालें।","छाने हुए चावल, बचा हुआ नमक और पानी डालें, एक बार चलाएँ, फिर बर्तन को फ़ॉइल से बंद करें और उसमें कई छेद कर दें।","पहले केवल मांस रखें: उसे ट्रे के ऊपर ओवन की रैक पर रखें, फ़ॉइल का तंबू बनाकर ढकें और 1¼ घंटे पकाएँ, फिर चावल का बर्तन सबसे निचली शेल्फ़ पर ठीक मांस के नीचे रखें ताकि उसका रस छेद वाले फ़ॉइल से टपके।","45 मिनट और पकाएँ जब तक मांस नरम न हो जाए और चावल पानी सोख न ले, फिर मांस को खोलकर 10 मिनट भूरा करें।","हसावी स्वाद के लिए: जलता हुआ कोयला या खजूर की डाली का टुकड़ा एक धातु के कटोरे में, बंद किए हुए ओवन के अंदर चावल और मांस के साथ रखें, 5 मिनट बंद रखें, फिर धुआँ निकलने देने के लिए दरवाज़ा सावधानी से खोलें।","चावल के ऊपर बकरे का मांस रखकर हरे सलाद और कम वसा वाली लबन के साथ परोसें।"],
["क्या बदला गया: बकरे का मांस स्वाभाविक रूप से कम वसा वाला होता है और दिखने वाली चर्बी हटाई गई है, केवल 2 छोटे चम्मच घी, स्टॉक क्यूब नहीं और नमक बहुत कम।","किडनी के लिए सुझाव: बकरे का मांस, टमाटर और शिमला मिर्च पोटैशियम बढ़ाते हैं; पका मांस 90–100 ग्राम तक ही रखें और टमाटर आधा कर सकते हैं।","मधुमेह के लिए सुझाव: एक प्लेट में लगभग 46 ग्राम कार्बोहाइड्रेट होता है; बड़े सलाद के साथ परोसें और चावल में एक चौथाई ब्राउन राइस मिला सकते हैं।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग (encyclopediacooking.com), अल-मदीना अख़बार (हसावी मंदी), अरबी विकिपीडिया (मंदी)"],[]),
(8582981,"भिंडी और मांस की सब्ज़ी","भिंडी के साथ मांस सऊदी घरों की रोज़ की सब्ज़ी है: मांस को टमाटर की सॉस में पकाया जाता है, फिर लहसुन और धनिये के तड़के में उछाली हुई भिंडी डाली जाती है, और इसे चावल के साथ परोसा जाता है। इस नुस्खे में कम वसा वाला मेमना, बहुत कम तेल, बिना नमक वाला टमाटर पेस्ट है और स्टॉक क्यूब नहीं हैं।","4","1 प्लेट (लगभग 420 ग्राम)",
["500 ग्राम कम वसा वाली मेमने की जाँघ, मध्यम टुकड़ों में कटी हुई","2 मध्यम प्याज़, कटे हुए (200 ग्राम)","1 बड़ा चम्मच ऑलिव ऑयल (13.5 ग्राम)","4 टमाटर, कद्दूकस किए हुए (400 ग्राम)","1 बड़ा चम्मच बिना नमक वाला टमाटर पेस्ट (15 ग्राम)","1 छोटा चम्मच मिश्रित सऊदी मसाला (बज़ार), ½ छोटा चम्मच जीरा और ½ पिसा सूखा नींबू (लूमी)","⅔ छोटा चम्मच नमक (4 ग्राम)","लहसुन के तड़के के लिए::2 छोटे चम्मच ऑलिव ऑयल (9 ग्राम)","लहसुन के तड़के के लिए::4 लहसुन की कलियाँ, कुटी हुई (15 ग्राम)","लहसुन के तड़के के लिए::1 छोटा गुच्छा ताज़ा धनिया, कटा हुआ (30 ग्राम)","लहसुन के तड़के के लिए::1 छोटा चम्मच पिसा धनिया","लहसुन के तड़के के लिए::500 ग्राम छोटी भिंडी, ताज़ी या जमी हुई","सजाने और परोसने के लिए::½ नींबू का रस (15 मिलीलीटर)"],
["मांस से दिखने वाली चर्बी हटा दें। बर्तन में एक बड़ा चम्मच तेल गरम करें और प्याज़ को सुनहरा होने तक पकाएँ।","मांस डालें और सब तरफ़ से भूरा होने तक पलटें, फिर टमाटर, पेस्ट, मसाले, जीरा, सूखा नींबू और 500 मिलीलीटर गरम पानी डालें।","ढक दें और लगभग 1 घंटा धीमी आँच पर पकाएँ जब तक मांस लगभग नरम न हो जाए, ज़रूरत हो तो थोड़ा पानी डालें।","तड़के के लिए: कड़ाही में तेल गरम करें और लहसुन को 30 सेकंड चलाएँ, ताज़ा और पिसा धनिया डालें, फिर भिंडी डालें और 3–4 मिनट उछालें।","भिंडी का मिश्रण नमक के साथ मांस में डालें और 15–20 मिनट धीमी आँच पर पकाएँ जब तक भिंडी नरम और सॉस गाढ़ी न हो जाए।","नींबू का रस डालें और चावल के साथ गरम परोसें।"],
["क्या बदला गया: कम वसा वाला, छँटा हुआ मेमना, सामान्य से बहुत कम तेल, भिंडी को तलने की जगह लहसुन के तड़के में उछालना, और बिना नमक वाला टमाटर पेस्ट तथा स्टॉक क्यूब नहीं।","किडनी के लिए सुझाव: भिंडी, टमाटर और टमाटर पेस्ट में पोटैशियम अधिक होता है; केवल 2 टमाटर लें, तड़के से पहले भिंडी को उबालकर पानी फेंक दें, और सादे सफ़ेद चावल के साथ छोटी प्लेट ही लें।","मधुमेह के लिए सुझाव: सब्ज़ी में लगभग 20 ग्राम कार्बोहाइड्रेट होता है; इसे 150 ग्राम पके चावल के साथ परोसें, अच्छा हो कि ब्राउन राइस या आधा दलिया (बुलगुर) हो।","इनके लिए उपयुक्त: मधुमेह, हृदय स्वास्थ्य और रक्तचाप वाले लोग, ग्लूटेन-मुक्त आहार।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, सैयदाती किचन, वेबतेब"],[]),
(8595227,"घी और शहद वाली दक्षिणी फत्ता","दक्षिणी फत्ता दक्षिणी सऊदी अरब (असीर, अल-बाहा और नजरान) का पारंपरिक नाश्ता है: साबुत गेहूँ की तवे की रोटियों को हाथ से तोड़कर तुलसी की सुगंध वाले घी और शहद के साथ परोसा जाता है। इस नुस्खे में प्रति सर्विंग 1 छोटे चम्मच से कम घी, आटे में चीनी नहीं और कम शहद है।","6","1 छोटा कटोरा (लगभग 90 ग्राम)",
["आटे के लिए::300 ग्राम साबुत गेहूँ का आटा","आटे के लिए::½ छोटा चम्मच कलौंजी","आटे के लिए::1 चुटकी नमक (1 ग्राम)","आटे के लिए::लगभग 400 मिलीलीटर पानी","आटे के लिए::तवा पोंछने के लिए 1 छोटा चम्मच ऑलिव ऑयल (4.5 ग्राम)","तुलसी वाले घी के लिए::1 बड़ा चम्मच साबुत गेहूँ का आटा (8 ग्राम)","तुलसी वाले घी के लिए::25 ग्राम घी (लगभग 5 छोटे चम्मच)","तुलसी वाले घी के लिए::1 छोटा गुच्छा तुलसी, धोकर सुखाई हुई (10 ग्राम)","परोसने के लिए::3 बड़े चम्मच सिद्र शहद (60 ग्राम)"],
["आटे को कलौंजी और नमक के साथ मिलाएँ, फिर धीरे-धीरे पानी डालकर फेंटें और केक के घोल से थोड़ा गाढ़ा घोल बना लें। इसे 30 मिनट रखा रहने दें।","तवा या नॉन-स्टिक कड़ाही मध्यम आँच पर गरम करें और किचन पेपर से थोड़ा तेल लगाकर पोंछ लें।","एक करछुल घोल डालें और पतला गोल फैलाएँ। नीचे से भूरा होने तक पकाएँ, पलटें और दूसरी तरफ़ भूरा करें। बाकी घोल से भी ऐसे ही बनाएँ।","तुलसी वाले घी के लिए: एक चम्मच आटे को छोटी कड़ाही में धीमी आँच पर सुनहरा और सुगंधित होने तक भूनें। घी डालें; जब वह पिघलकर झाग देने लगे तो तुलसी डालें, एक मिनट से कम ढककर रखें, फिर आँच बंद करें, थोड़ा ठंडा होने दें और छान लें।","गरम रोटियों को हाथ से मध्यम टुकड़ों में परोसने के बर्तन में तोड़ लें।","रोटी पर तुलसी वाला घी और फिर शहद डालें और कम वसा वाले दूध, चाय या कॉफ़ी के साथ गरम परोसें।"],
["क्या बदला गया: सारा आटा साबुत गेहूँ का है, आटे से चीनी हटा दी गई है, छह लोगों के लिए 25 ग्राम घी है न कि मक्खन की पूरी टिकिया, और शहद प्रति सर्विंग 10 ग्राम तक घटाया गया है।","किडनी के लिए सुझाव: साबुत गेहूँ के आटे में मैदे से अधिक फॉस्फोरस और पोटैशियम होता है; आप आधा साबुत गेहूँ और आधा मैदा ले सकते हैं, एक ही हिस्सा खाएँ, और दूध की जगह चाय या हल्की कॉफ़ी पिएँ।","मधुमेह के लिए सुझाव: एक हिस्से में लगभग 45 ग्राम कार्बोहाइड्रेट होता है, जिसमें 8 ग्राम मिलाई गई चीनी शामिल है; शहद अलग से परोसें और कम डालें, और ब्लड शुगर की बढ़त धीमी करने के लिए उसके साथ उबला अंडा या कम वसा वाली लबन खाएँ।","इनके लिए उपयुक्त: हृदय स्वास्थ्य और रक्तचाप वाले लोग, किडनी रोग (डायलिसिस पर नहीं), डायलिसिस पर रहने वाले लोग, शाकाहारी।","संदर्भ: एनसाइक्लोपीडिया कुकिंग, सऊदीपीडिया (असीर के लोक व्यंजन), मौज़ू3"],[]),
]
P(1,R)
